import { CheckCircle2, FileClock, ReceiptText, Scale } from 'lucide-react';

import type { AdminAccountingJournalBatch, AdminAccountingJournalBatchSummary } from '../../../lib/admin-api';
import { adminGet } from '../../../lib/admin-api';
import { AdminFilterPanel } from '../../../components/admin-filter-panel';
import {
  AdminFormActionRow,
  AdminFormControlButton,
  AdminFormSearch,
  AdminFormShell,
} from '../../../components/admin-form-controls';
import { AdminInlineFallback } from '../../../components/admin-inline-fallback';
import { AdminPageTemplate } from '../../../components/admin-page-template';
import { AdminTextLink } from '../../../components/admin-text-link';
import { DateTimeText } from '../../../components/date-time-text';
import { MoneyText } from '../../../components/money-text';
import { StatusBadgeFromPillClass } from '../../../components/status-badge';
import { formatMoney, shortId } from '../../../lib/admin-format';
import { dateRangeLabel } from '../../../lib/date-range';
import { FinanceDataTable } from '../finance-data-table';
import { financePersonName } from '../finance-participant-label';
import { FinanceListFilterLinks, FINANCE_LIST_DATE_RANGE_LINKS } from '../finance-list-filter-links';
import { FinanceListCommandBoard, FinanceListCommandCard, formatFinancePercent } from '../finance-list-command-card';
import { financeJournalBatchStatusPill } from '../finance-status-badge-model';
import { FinanceTablePaginationFooter } from '../finance-table-pagination-footer';
import { FinanceTablePanel } from '../finance-table-panel';
import { TaxFinanceWorkflowActions } from '../tax-finance-workflow-actions';
import {
  GENERAL_LEDGER_REVIEW_LINKS,
  FINANCE_ACCOUNTING_PAGE_SIZE_LINKS,
  buildAccountingJournalBatchApiHref,
  buildAccountingJournalBatchSummaryApiHref,
  buildTaxFinanceWorkflowLinks,
  buildTaxSettlementServerPagination,
  emptyAccountingJournalBatchSummary,
  financeAccountingReviewLabel,
  generalLedgerDetailHref,
  generalLedgerHref,
  readBookingSettlementFilters,
  readFinanceAccountingFilters,
  readMonthlyTaxClosingFilters,
  readPartnerWithholdingTaxFilters,
} from '../tax-settlement-page-model';

type GeneralLedgerPageProps = {
  readonly searchParams?: Promise<Record<string, string | string[] | undefined>>;
};

export default async function GeneralLedgerPage({ searchParams }: GeneralLedgerPageProps) {
  const params = searchParams ? await searchParams : {};
  const filters = readFinanceAccountingFilters(params, 'needs-action');
  const ledgerQuery = readParam(params, 'q').trim();
  const settlementFilters = readBookingSettlementFilters(params);
  const monthlyFilters = readMonthlyTaxClosingFilters(params);
  const withholdingFilters = readPartnerWithholdingTaxFilters(params);
  const overviewFilters = { ...filters, page: 1, review: 'all' as const };
  const [queueSummary, overviewSummary, batches] = await Promise.all([
    adminGet<AdminAccountingJournalBatchSummary>(
      generalLedgerApiHref(buildAccountingJournalBatchSummaryApiHref(filters), ledgerQuery),
      emptyAccountingJournalBatchSummary(),
    ),
    adminGet<AdminAccountingJournalBatchSummary>(
      buildAccountingJournalBatchSummaryApiHref(overviewFilters),
      emptyAccountingJournalBatchSummary(),
    ),
    adminGet<AdminAccountingJournalBatch[]>(
      generalLedgerApiHref(buildAccountingJournalBatchApiHref(filters), ledgerQuery),
      [],
    ),
  ]);
  const pagination = buildTaxSettlementServerPagination(batches, filters, queueSummary.count);
  const rangeScope = dateRangeLabel(filters.range);
  const queueHref = (nextFilters = filters, query = ledgerQuery) =>
    generalLedgerQueueHref(nextFilters, query);

  return (
    <AdminPageTemplate
      actions={
        <TaxFinanceWorkflowActions
          links={buildTaxFinanceWorkflowLinks({
            accountingFilters: filters,
            current: 'general-ledger',
            monthlyFilters,
            settlementFilters,
            withholdingFilters,
          })}
        />
      }
      description="Bounded journal batch lookup for booking settlement, reversal, manual adjustment, refund, payout, and bank reconciliation evidence."
      title="General Ledger"
    >
      <FinanceListCommandBoard ariaLabel="Ledger command board">
        <FinanceListCommandCard
          detail={`${formatMoney(
            overviewSummary.unbalancedAmount,
            overviewSummary.currency,
          )} across journal batches whose debit and credit totals do not agree.`}
          href={queueHref({ ...filters, page: 1, review: 'unbalanced' }, '')}
          icon={Scale}
          label="Unbalanced journals"
          scope={overviewSummary.unbalancedCount > 0 ? 'Needs action' : rangeScope}
          tone={overviewSummary.unbalancedCount > 0 ? 'danger' : 'success'}
          value={overviewSummary.unbalancedCount > 0 ? overviewSummary.unbalancedCount : 'Balanced'}
        />
        <FinanceListCommandCard
          detail={`${overviewSummary.draftCount} journal batch(es) are not posted and need Finance review.`}
          href={queueHref({ ...filters, page: 1, review: 'draft' }, '')}
          icon={FileClock}
          label="Draft journals"
          scope={overviewSummary.draftCount > 0 ? 'Needs action' : rangeScope}
          tone={overviewSummary.draftCount > 0 ? 'warning' : 'success'}
          value={overviewSummary.draftCount}
        />
        <FinanceListCommandCard
          detail={`${overviewSummary.postedCount} of ${overviewSummary.count} period journal batch(es) are posted.`}
          href={queueHref({ ...filters, page: 1, review: 'posted' }, '')}
          icon={CheckCircle2}
          label="Posted records"
          scope={rangeScope}
          tone={overviewSummary.postedCount > 0 ? 'success' : 'neutral'}
          value={formatFinancePercent(overviewSummary.postedCount, overviewSummary.count)}
        />
        <FinanceListCommandCard
          detail={`${overviewSummary.reversedCount} historical reversal batch(es) retain their original audit trail.`}
          href={queueHref({ ...filters, page: 1, review: 'reversed' }, '')}
          icon={ReceiptText}
          label="Reversed records"
          scope={rangeScope}
          tone="neutral"
          value={overviewSummary.reversedCount}
        />
      </FinanceListCommandBoard>

      <AdminFilterPanel
        className="admin-mb-16"
        description={generalLedgerFilterDescription({
          page: pagination.page,
          q: ledgerQuery,
          range: filters.range,
          review: filters.review,
          totalPages: pagination.totalPages,
        })}
        resultLabel={`${pagination.pageSize} per page`}
        resultTone="success"
        title="General ledger filters"
      >
        <AdminFormShell action="/finance-tax/general-ledger" className="filter-form admin-mb-12" method="get">
          <input name="range" type="hidden" value={filters.range} />
          <input name="review" type="hidden" value={filters.review} />
          <input name="take" type="hidden" value={filters.take} />
          <AdminFormSearch
            defaultValue={ledgerQuery}
            label="Search journal batches"
            name="q"
            placeholder="Journal source, booking, payment, period"
          />
          <AdminFormActionRow>
            <AdminFormControlButton className="button-primary" type="submit">Search</AdminFormControlButton>
            {ledgerQuery ? (
              <AdminTextLink href={queueHref({ ...filters, page: 1 }, '')}>Clear</AdminTextLink>
            ) : null}
          </AdminFormActionRow>
        </AdminFormShell>
        <FinanceListFilterLinks
          groups={[
            {
              id: 'review',
              links: GENERAL_LEDGER_REVIEW_LINKS.map((item) => ({
                active: filters.review === item.review,
                activePillClassName:
                  item.review === 'needs-action' || item.review === 'unbalanced'
                    ? 'pill-warn'
                    : 'pill-info',
                href: queueHref({ ...filters, page: 1, review: item.review }),
                id: item.review,
                label: item.label,
              })),
            },
            {
              id: 'range',
              links: FINANCE_LIST_DATE_RANGE_LINKS.map(([label, range]) => ({
                active: filters.range === range,
                activePillClassName: 'pill-info',
                href: queueHref({ ...filters, page: 1, range }),
                id: range,
                label,
              })),
            },
            {
              id: 'take',
              links: FINANCE_ACCOUNTING_PAGE_SIZE_LINKS.map((take) => ({
                active: filters.take === take,
                activePillClassName: 'pill-success',
                href: queueHref({ ...filters, page: 1, take }),
                id: take,
                label: `${take} rows`,
              })),
            },
          ]}
        />
      </AdminFilterPanel>

      <FinanceTablePanel
        grouped
        description={generalLedgerTableDescription(filters.review)}
        resultLabel={`${pagination.totalRows} batch(es)`}
        resultTone={generalLedgerResultTone(filters.review, pagination.totalRows)}
        title={financeAccountingReviewLabel(filters.review, GENERAL_LEDGER_REVIEW_LINKS)}
      >
        <FinanceDataTable
          emptyMessage="No journal batches match the current filters."
          headers={['Journal', 'Related context', 'Period', 'Debit / Credit', 'Integrity', 'Open']}
          rowCount={pagination.rows.length}
        >
          {pagination.rows.map((batch) => (
            <tr key={batch.id}>
              <td>
                <AdminTextLink href={generalLedgerDetailHref(batch.id)}>
                  <strong>{generalLedgerSourceLabel(batch.sourceType)}</strong>
                </AdminTextLink>
                <div className="muted">Source {shortId(batch.sourceId)}</div>
                <div className="muted">{batch._count?.entries ?? 0} entries</div>
              </td>
              <td>
                {batch.bookingId ? (
                  <div>
                    <AdminTextLink href={`/bookings/${batch.bookingId}`}>
                      Booking {shortId(batch.bookingId)}
                    </AdminTextLink>
                    <span className="muted"> · {batch.booking?.status ?? 'Unknown status'}</span>
                  </div>
                ) : (
                  <AdminInlineFallback>No booking</AdminInlineFallback>
                )}
                {batch.customerProfileId ? (
                  <div className="admin-mt-6">
                    <AdminTextLink href={`/customers/${batch.customerProfileId}`}>
                      {financePersonName(batch.customerProfile?.user, 'Unknown customer')}
                    </AdminTextLink>
                    <span className="muted"> · Customer</span>
                  </div>
                ) : null}
                {batch.providerProfileId ? (
                  <div className="admin-mt-6">
                    <AdminTextLink href={`/partners/${batch.providerProfileId}?section=full`}>
                      {batch.providerProfile?.displayName ??
                        financePersonName(batch.providerProfile?.user, 'Unknown partner')}
                    </AdminTextLink>
                    <span className="muted"> · Partner</span>
                  </div>
                ) : null}
                {batch.paymentId ? (
                  <div className="muted admin-mt-6">Payment {shortId(batch.paymentId)}</div>
                ) : null}
              </td>
              <td>
                {batch.monthlyPeriod ? (
                  <strong>{batch.monthlyPeriod}</strong>
                ) : (
                  <AdminInlineFallback>No monthly period</AdminInlineFallback>
                )}
                <div className="muted">
                  <DateTimeText value={batch.postedAt} />
                </div>
              </td>
              <td>
                <strong>
                  <MoneyText amount={batch.totalDebit} currency={batch.currency} />
                </strong>
                <div className="muted">
                  Credit <MoneyText amount={batch.totalCredit} currency={batch.currency} />
                </div>
              </td>
              <td>
                <StatusBadgeFromPillClass pillClass={financeJournalBatchStatusPill(batch.status)}>
                  {generalLedgerStatusLabel(batch.status)}
                </StatusBadgeFromPillClass>
                <div className="admin-mt-6">
                  <StatusBadgeFromPillClass
                    pillClass={batch.totalDebit === batch.totalCredit ? 'pill-success' : 'pill-danger'}
                  >
                    {batch.totalDebit === batch.totalCredit ? 'Balanced' : 'Unbalanced'}
                  </StatusBadgeFromPillClass>
                </div>
                {batch.totalDebit !== batch.totalCredit ? (
                  <div className="muted admin-mt-6">
                    Delta{' '}
                    <MoneyText
                      amount={Math.abs(batch.totalDebit - batch.totalCredit)}
                      currency={batch.currency}
                    />
                  </div>
                ) : null}
                {batch.reversedAt ? (
                  <div className="muted admin-mt-8">
                    <DateTimeText value={batch.reversedAt} />
                  </div>
                ) : null}
              </td>
              <td>
                <AdminTextLink href={generalLedgerDetailHref(batch.id)}>Open detail</AdminTextLink>
              </td>
            </tr>
          ))}
        </FinanceDataTable>
        <FinanceTablePaginationFooter
          ariaLabel="General ledger pages"
          hrefForPage={(page) => queueHref({ ...filters, page })}
          pagination={pagination}
        />
      </FinanceTablePanel>
    </AdminPageTemplate>
  );
}

function generalLedgerApiHref(href: string, query: string) {
  return query ? appendQueryParam(href, 'q', query) : href;
}

function generalLedgerQueueHref(
  filters: Parameters<typeof generalLedgerHref>[0],
  query: string,
) {
  return generalLedgerApiHref(generalLedgerHref(filters), query);
}

function generalLedgerFilterDescription(input: {
  page: number;
  q: string;
  range: Parameters<typeof generalLedgerHref>[0]['range'];
  review: Parameters<typeof generalLedgerHref>[0]['review'];
  totalPages: number;
}) {
  const parts = [
    `Showing page ${input.page} of ${input.totalPages}.`,
    `Queue: ${financeAccountingReviewLabel(input.review, GENERAL_LEDGER_REVIEW_LINKS)}.`,
    `Range: ${dateRangeLabel(input.range)}.`,
  ];
  if (input.q) parts.push(`Search: ${input.q}.`);
  return parts.join(' ');
}

function generalLedgerTableDescription(
  review: Parameters<typeof generalLedgerHref>[0]['review'],
) {
  if (review === 'needs-action') {
    return 'Oldest draft or unbalanced journal batches appear first. Resolve the source evidence before monthly close.';
  }
  if (review === 'unbalanced') {
    return 'Journal batches whose debit and credit totals disagree, ordered from oldest to newest.';
  }
  if (review === 'draft') {
    return 'Draft journal batches awaiting Finance review, ordered from oldest to newest.';
  }
  if (review === 'reversed') {
    return 'Historical reversal journals. Open detail to inspect the retained original and reversal evidence.';
  }
  return 'Journal records are ordered newest first. Open detail only when entry-level evidence is required.';
}

function generalLedgerResultTone(
  review: Parameters<typeof generalLedgerHref>[0]['review'],
  count: number,
) {
  if (review === 'needs-action' || review === 'unbalanced') {
    return count > 0 ? 'warning' as const : 'success' as const;
  }
  if (review === 'draft') return count > 0 ? 'warning' as const : 'success' as const;
  if (review === 'posted') return 'success' as const;
  return 'info' as const;
}

function generalLedgerSourceLabel(sourceType: AdminAccountingJournalBatch['sourceType']) {
  return sourceType
    .toLowerCase()
    .split('_')
    .map((part) => `${part.charAt(0).toUpperCase()}${part.slice(1)}`)
    .join(' ');
}

function generalLedgerStatusLabel(status: AdminAccountingJournalBatch['status']) {
  if (status === 'DRAFT') return 'Draft';
  if (status === 'REVERSED') return 'Reversed';
  return 'Posted';
}

function appendQueryParam(href: string, key: string, value: string) {
  const url = new URL(href, 'http://localhost');
  url.searchParams.set(key, value);
  return `${url.pathname}${url.search}`;
}

function readParam(params: Record<string, string | string[] | undefined>, key: string) {
  const value = params[key];
  return Array.isArray(value) ? (value[0] ?? '') : (value ?? '');
}
